from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework_simplejwt.tokens import RefreshToken
from django.shortcuts import get_object_or_404
from django.contrib.auth import get_user_model

User = get_user_model()

class SupportImpersonationTokenView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        if not request.user.groups.filter(name="SupportAgent").exists():
            return Response({"detail": "Support credentials required"}, status=403)

        target_user_id = request.data.get("target_user_id")
        target_user = get_object_or_404(User, id=target_user_id)

        if not request.user.assigned_support_tenants.filter(id=target_user.tenant_id).exists():
            return Response({"detail": "Target user is outside your authorized support scope"}, status=403)

        refresh = RefreshToken.for_user(target_user)
        return Response({
            "access": str(refresh.access_token),
            "refresh": str(refresh)
        })
